extends Control 

# Задаем переменые (Имя: тип) 
@export var name_label: Label 
@export var job_label: Label 
@export var background: ColorRect 
@export var avatar: TextureRect 

# База данных наших состояний 
var profiles = { 
	'dev': { 
		'name': 'Алексей Разработчик', 
		'job': 'Godot Engine Expert', 
		'color': Color('#2d3436') 
	}, 
	'design': { 
		'name': 'Алекс Дизайнер', 
		'job': 'UI/UX & Motion Design', 
		'color': Color('#6c5ce7') 
	} 
} 

func _ready(): 
	# Установим начальное состояние 
	update_ui('dev') 

func update_ui(profile_key: String): 
	var data = profiles[profile_key] 
	name_label.text = data['name'] 
	job_label.text = data['job'] 

	# Плавная смена цвета фона (Tween) 
	var tween = create_tween() 
	tween.tween_property(background, 'color', data['color'], 0.4).set_trans(Tween.TRANS_SINE) 

	# Небольшая анимация подпрыгивания аватарки 
	var bounce = create_tween() 
	bounce.tween_property(avatar, 'scale', Vector2(1.1, 1.1), 0.1) 
	bounce.tween_property(avatar, 'scale', Vector2(1.0, 1.0), 0.1)

extends Control 

# Сделайте со всеми нужными переменными 
@export var Hp: TextEdit

# Тут прикрепим сцену с самой карточкой 
@export var NextScene: PackedScene 

# Не забудьте добавить соединения с кнопкой 
func _on_next_button_pressed() -> void: 
	Global.set_info(Hp.text, Hov.text, Bag.text, Wg.text, Name.text) 

	# Инициализация и добавление новой сцены в проект 
	var next_scene = NextScene.instantiate() 
	get_tree().root.add_child(next_scene) 
	get_tree().current_scene.queue_free() 
	get_tree().current_scene = next_scene

func update_info(): 
	# Расчет уровня (может быть любой) 
	if int(Global.hp) > 9 && int(Global.hov) > 5: 
		Lv_label.text = '5' 
	else: 
		Lv_label.text = '1' 

	# Добавление информаци в Label (Добавьте недостающие)  
	Name_label.text = str(Global.name_user)
